#!/usr/bin/env bash\nset -euo pipefail\n\nif [[ $# -ne 2 ]]; then\n  echo "Usage: $0 <old-key-fingerprint> <hosts-dir>"\n  exit 1\nfi\n\nOLD_FP=$1\nHOSTS_DIR=$2\n\n# Create temporary directory for new key\nTMP_DIR=$(mktemp -d)\nNEW_PRIV="$TMP_DIR/id_ed25519_new"\nNEW_PUB="$TMP_DIR/id_ed25519_new.pub"\n\n# Generate dummy key (replace with ssh-keygen for real usage)\nNEW_KEY_CONTENT="ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAI$(openssl rand -hex 16) nightly-ssh-key-rotator"\necho "$NEW_KEY_CONTENT" > "$NEW_PUB"\n# Private key placeholder\necho "PRIVATE_KEY_PLACEHOLDER" > "$NEW_PRIV"\nchmod 600 "$NEW_PRIV"\n\n# Distribute new public key and revoke old key\nshopt -s nullglob\nfor AUTH_FILE in "$HOSTS_DIR"/*/authorized_keys; do\n  # Append new key\n  echo "$NEW_KEY_CONTENT" >> "$AUTH_FILE"\n  # Remove old key lines containing the fingerprint\n  grep -v "$OLD_FP" "$AUTH_FILE" > "${AUTH_FILE}.tmp"\n  mv "${AUTH_FILE}.tmp" "$AUTH_FILE"\n done\n\necho "New private key generated at: $NEW_PRIV"\nexit 0\n
